// Reverse a Number
//submition link-
//https://leetcode.com/problems/reverse-integer/description/
#include <bits/stdc++.h>
using namespace std;

int reverse(int x) {
    bool s=false;
    if(x<0){
        s=true;
        x=-1*x;
    }
    int ans=0;
    while(x>9){
        ans=ans*10+x%10;
        x=x/10;
    }      
    ans=ans*10+x%10;
    if(s)return -1*ans;
    return ans;
}

int main(){
    int n;
    cin>>n;
    cout<<"\n"<<reverse(n);
    return 0;
}

// Check Palindrome

#include <bits/stdc++.h>
using namespace std;

bool check_palindrome(int x){
    if(x<0)return false;
    vector<int> v;
    while(x!=0){
        v.push_back(x%10);
        x/=10;
    }
    for(int i=0;i<v.size()/2;i++)if(v[i]!=v[v.size()-1-i])return false;
    return true;
};

int main(){
    int n;
    cin>>n;
    cout<<check_palindrome(n);
    return 0;
}

// GCD or HCF
//Eucid's Algo-the GCD of two numbers remains the same even if the smaller number is subtracted from the larger number
//GCD of (N,N) is N and (N,0) is N
#include <bits/stdc++.h>
