// Find the highest/lowest frequency element
//submit link-https://leetcode.com/problems/frequency-of-the-most-frequent-element/
#include <bits/stdc++.h>
using namespace std;
int maxFrequency(vector<int>& nums, long long k) {
        sort(nums.begin(), nums.end());
        long long l=0,r=0,ans=1,sum=0;
        for (r = 0; r < nums.size(); r++) {
            sum+=nums[r];
            while((long long)nums[r]*(r-l+1)-sum>k) {
                sum-= nums[l];
                l++;
            }
            ans = max(ans,r-l+1);
        }
        return ans;
    }
int main(){
    vector<int> arr={2,3,1,2,3,6,44,6,8,5};
    int k=4;
    cout<<maxFrequency(arr,5);
    return 0;
}

// Selection Sort

#include <bits/stdc++.h>
using namespace std;

void selection_sort(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        int mini = i;
        for (int j = i + 1; j < n; j++)if (arr[j] < arr[mini])mini = j;
        int temp = arr[mini];
        arr[mini] = arr[i];
        arr[i] = temp;
    }
    cout << "After selection sort: " << "\n";
    for (int i = 0; i < n; i++)cout << arr[i] << " ";
    cout << "\n";
}

int main() {
    int arr[] = {13, 46, 24, 52, 20, 9};
    int n = sizeof(arr) / sizeof(arr[0]);
    cout << "Before selection sort: " << "\n";
    for (int i = 0; i < n; i++)cout << arr[i] << " ";
    cout << "\n";
    selection_sort(arr, n);
    return 0;
}

// Bubble Sort

#include <bits/stdc++.h>
using namespace std;

void bubble_sort(vector<int>& arr) {
    int n = arr.size();
    for (int i = n - 1; i >= 0; i--){
        int didSwap = 0;
        for (int j = 0; j <= i - 1; j++){
            if(arr[j] > arr[j + 1]){
                swap(arr[j],arr[j + 1]);
                didSwap = 1;
            }
        }
        if(didSwap == 0)break;
    }
    cout << "After Using Bubble Sort:\n";
    for (int num : arr)cout << num << " ";
    cout << endl;
}


int main() {
    vector<int> arr = {13, 46, 24, 52, 20, 9};
    cout << "Before Using Bubble Sort:\n";
    for (int num : arr) {
        cout << num << " ";
    }
    cout << endl;
    bubble_sort(arr);
    return 0;
}

// Insertion Sort

#include <bits/stdc++.h>
using namespace std;
vector<int> insertionSort(vector<int>& nums) {
    int n = nums.size();
    for (int i = 1; i < n; i++) {
        int key = nums[i];
        int j = i - 1; 
        while (j >= 0 && nums[j] > key) {
            nums[j + 1] = nums[j];
            j--;
        }
        nums[j + 1] = key;
    }
    return nums;
}


