string removeOuterParentheses(string s) {
    string res;
    int opened = 0;

    for (auto c : s) {
        if (c == '(') {
            if (opened > 0)
                res += c;
            opened++;
        } else {
            if (opened > 1)
                res += c;
            opened--;
        }
    }

    return res;
}

string reverseWords(string s) {
    string ans = "";
    int start = -1, end = -1;
    for(int i=0; i<s.size(); i++){
        while(s[i]==' ')
            i++;
        start = i;
        while(i<s.size() && s[i]!=' ')
            i++;
        end = i;
        string temp = s.substr(start,end-start);
        reverse(temp.begin(),temp.end());
        ans = ans+" "+temp;
    }
    reverse(ans.begin(),ans.end());
    int i=0, j=ans.size()-1;
    while(ans[i]==' ')
        i++;
    while(ans[j]==' ')
        j--;
    ans = ans.substr(i,j-i+1);
    return ans;
}

string largestOddNumber(string num) {
    // Check the first odd number from last
    for (int i = num.size() - 1; i >= 0; i--) {
        if ((num[i] - '0') % 2 != 0)
            return num.substr(0, i + 1);
    }
    return "";
}

using namespace std;

string longestCommonPrefix(vector<string>& strs) {
    if (strs.empty())
        return "";

    sort(strs.begin(), strs.end());

    int first = 0, last = strs.size() - 1;
    int i = 0, j = 0;
    int len = 0;

    while (i < strs[first].size() && j < strs[last].size() && strs[first][len] == strs[last][len]) {
        i++;
        j++;
        len++;
    }

    return strs[first].substr(0, len);
}

bool isIsomorphic(string s, string t) {
    unordered_map<char, char> mps;
    unordered_map<char, char> mpt;

    for (int i = 0; i < s.size(); i++) {
        if (mps.find(s[i]) == mps.end() && mpt.find(t[i]) == mpt.end()) {
            mps[s[i]] = t[i];
            mpt[t[i]] = s[i];
        } else if (mps[s[i]] != t[i] || mpt[t[i]] != s[i]) {
            return false;
        }
    }

    return true;
}

bool rotateString(string s, string goal) {
    if (s.size() != goal.size())
        return false;
    if ((s + s).find(goal) == string::npos)
        return false;
    return true;
}

bool isAnagram(string s, string t) {
    unordered_map<char,int>mp;
    for(auto c:s)
        mp[c]++;
    for(auto c:t){
        if(mp.find(c)==mp.end())
            return false;
        mp[c]--;
        if(mp[c]==0)
            mp.erase(c);
    }
    return (mp.size()==0);
}

string frequencySort(string s) {
    unordered_map<char, int> mp;
    for (auto c : s) {
        mp[c]++;
    }

    priority_queue<pair<int, char>> pq;
    for (auto it : mp) {
        pq.push({ it.second, it.first });
    }

    string ans = "";
    while (!pq.empty()) {
        auto curr = pq.top();
        pq.pop();
        ans.append(curr.first, curr.second);
    }

    return ans;
}

int maxDepth(string s) {
    int opened = 0, ans = 0;
    for (auto c : s) {
        if (c == '(') {
            opened++;
            ans = max(ans, opened);
        } else if (c == ')') {
            opened--;
        }
    }
    return ans;
