                *head_ref = curr->next;
                curr->next->prev = NULL
            }
            // Last node
            else if (!curr->next) {
                curr->prev->next = curr->next;
            }
            // Middle node
            else {
                curr->next->prev = curr->prev;
                curr->prev->next = curr->next;
            }
        }
        curr = curr->next;
    }
}

vector<pair<int, int>> findPairsWithGivenSum(Node *head, int target)
{
    vector<pair<int, int>> ans;
    Node* start = head;
    Node* end = head;
    while (end->next) {
        end = end->next;
    }
    while (start->data < end->data) {
        int sum = start->data + end->data;
        if (sum == target) {
            ans.push_back({ start->data, end->data });
            start = start->next;
            end = end->prev;
        }
        else if (sum < target) {
            start = start->next;
        }
        else {
            end = end->prev;
        }
    }
    return ans;
}

