}

int getnum(int i, string& str)
{
    if (i < 0)
        return 0;

    if (i == 0) {
        if (str[i] == '-')
            return 0;

        int digit = str[i] - '0';
        if (0 <= digit && digit <= 9) {
            int prev = getnum(i - 1, str);
            if (prev != 1e9)
                return (prev * 10) + digit;
        }
        return 1e9;
    }

    int digit = str[i] - '0';
    if (0 <= digit && digit <= 9) {
        int prev = getnum(i - 1, str);
        if (prev != 1e9)
            return (prev * 10) + digit;
    }
    return 1e9;
}

int atoi(string str)
{
    int i = str.size() - 1;
    int ans = getnum(i, str);
    if (ans == 1e9)
        return -1;
    if (str[0] == '-')
        return -1 * ans;
    return ans;
}

const long long mod = 1e9 + 7;

int countGoodNumbers(long long n) {
    // Base case
    if (n == 1)
        return 5;

    if (n % 2 == 0)
        return (countGoodNumbers(n - 1) % mod * 4 % mod);
    else
        return (countGoodNumbers(n - 1) % mod * 5 % mod);
}

void insertAtBottom(int ele, stack<int>& stack) {
    if (stack.empty()) {
        stack.push(ele);
        return;
    }

    int temp = stack.top();
    stack.pop();
    insertAtBottom(ele, stack);
    stack.push(temp);
}

void reverseStack(stack<int>& stack) {
    if (stack.empty())
        return;

    int first = stack.top();
    stack.pop();
    reverseStack(stack);
    insertAtBottom(first, stack);
}

void placeAtCorrectPos(int ele, stack<int>& st) {
	if (st.empty() || st.top() < ele) {
		st.push(ele);
		return;
	}

	int first = st.top();
	st.pop();
	placeAtCorrectPos(ele, st);
	st.push(first);
}

void sortSt(stack<int>& st) {
	if (st.empty())
		return;

	int first = st.top();
	st.pop();
	sortSt(st);
	placeAtCorrectPos(first, st);
}

void solve(vector<string>& ans, string s, int open, int close, int n) {
	if (open == n && close == n){
		ans.push_back(s);
        return;
    }

	if (open <= n)
		solve(ans, s + '(', open + 1, close, n);
	if (open > close)
		solve(ans, s + ')', open, close + 1, n);
}

vector<string> generateParenthesis(int n) {
