vector<int> postorderTraversal(TreeNode* root) {
    if (!root) {
        return {};
    }
    vector<int> ans;
    stack<TreeNode*> st;
    TreeNode* curr = root;
    unordered_map<TreeNode*, bool> mp;
    pushLeft(curr, st, mp);
    while (!st.empty()) {
        curr = st.top();
        if (!curr->right || mp[curr->right]) {
            ans.push_back(curr->val);
            st.pop();
        }
        else {
            pushLeft(curr->right, st, mp);
        }
    }
    return ans;
}

