    int leftSum = max(0, solve(root->left, maxSum));
    int rightSum = max(0, solve(root->right, maxSum));
    int currentSum = root->val + leftSum + rightSum;
    maxSum = max(maxSum, currentSum);
    return root->val + max(leftSum, rightSum);
}

