// NOTE:- we are keeping track of levels because of the question condition but if no such condition exists, then no need of level only hd will work.

vector<vector<int>> verticalTraversal(TreeNode* root) {
    if (!root) return {};

    unordered_map<int, vector<pair<int, int>>> mp;
    int mini = 0, maxi = 0;
    queue<pair<int, TreeNode*>> q;
    q.push({0, root});

    int lvl = 0;
    while (!q.empty()) {
        int n = q.size();
        for (int i = 0; i < n; i++) {
            auto p = q.front();
            q.pop();
            TreeNode* curr = p.second;
            int hd = p.first;
            if (curr->left) {
                mini = min(mini, hd - 1);
                q.push({hd - 1, curr->left});
            }
            if (curr->right) {
                maxi = max(maxi, hd + 1);
                q.push({hd + 1, curr->right});
            }
            mp[hd].push_back({lvl, curr->val});
        }
        lvl++;
    }

    vector<vector<int>> ans;
    for (int i = mini; i <= maxi; i++) {
        sort(mp[i].begin(), mp[i].end());
        vector<int> temp;
        for (auto it : mp[i])
            temp.push_back(it.second);
        ans.push_back(temp);
    }

    return ans;
}

vector<int> getTopView(TreeNode<int> *root) {
    if (!root) return {};

    unordered_map<int, int> mp;
    int mini = 0, maxi = 0;
    queue<pair<int, TreeNode<int>*>> q;
    q.push({0, root});

    while (!q.empty()) {
        auto p = q.front();
        q.pop();
        TreeNode<int>* curr = p.second;
        int hd = p.first;
        if (curr->left) {
            mini = min(mini, hd - 1);
            q.push({hd - 1, curr->left});
        }
        if (curr->right) {
            maxi = max(maxi, hd + 1);
            q.push({hd + 1, curr->right});
        }
        if (mp.find(hd) == mp.end())
            mp[hd] = curr->data;
    }

    vector<int> ans;
    for (int i = mini; i <= maxi; i++) {
        ans.push_back(mp[i]);
    }

    return ans;
}

vector<int> getBottomView(TreeNode<int> *root) {
    if (!root) return {};

    unordered_map<int, pair<int, int>> mp;
    int mini = 0, maxi = 0;
    queue<pair<TreeNode<int>*, pair<int, int>>> q;
    q.push({root, {0, 0}});

    while (!q.empty()) {
        auto p = q.front();
        q.pop();
        TreeNode<int>* curr = p.first;
        int hd = p.second.first;
        int level = p.second.second;

        mp[hd] = {curr->data, level};
        mini = min(mini, hd);
        maxi = max(maxi, hd);

        if (curr->left) {
            q.push({curr->left, {hd - 1, level + 1}});
        }
        if (curr->right) {
            q.push({curr->right, {hd + 1, level + 1}});
        }
    }

    vector<int> ans;
    for (int i = mini; i <= maxi; i++) {
        ans.push_back(mp[i].first);
    }

    return ans;
}

vector<int> rightSideView(TreeNode* root) {
    if (!root) return {};

    vector<int> ans;
    queue<TreeNode*> q;
    q.push(root);

    while (!q.empty()) {
        int n = q.size();
        for (int i = 0; i < n; i++) {
            TreeNode* curr = q.front();
            q.pop();
            if (curr->left) {
                q.push(curr->left);
            }
            if (curr->right) {
                q.push(curr->right);
            }
            // Add only the last node of the level to the answer for right view in case of left view push only the first element
            if (i == n - 1) {
                ans.push_back(curr->val);
            }
        }
    }

    return ans;
}

