        if (order[i - 1] >= order[i]) {
            return false;
        }
    }
    return true;
}

TreeNode* searchBST(TreeNode* root, int val) {
    if (!root) return NULL;
    if (root->val == val) return root;
    if (root->val > val) return searchBST(root->left, val);
    else return searchBST(root->right, val);
}

