void solve(vector<vector<char>>& board) {
    int m = board.size(), n = board[0].size();
    vector<vector<char>> vis(board.begin(), board.end());

    // Perform DFS from border cells
    for(int i = 0; i < n; i++){
        if(vis[0][i] == 'O')
            dfs(0, i, vis);
        if(vis[m - 1][i] == 'O')
            dfs(m - 1, i, vis);
    }
    for(int i = 0; i < m; i++){
        if(vis[i][0] == 'O')
            dfs(i, 0, vis);
        if(vis[i][n - 1] == 'O')
            dfs(i, n - 1, vis);
    }

    // Update the original board
    for(int i = 0; i < m; i++){
        for(int j = 0; j < n; j++){
            if(vis[i][j] == 'O')
                board[i][j] = 'X';
        }
    }
}

