    // Create the adjacency list
    for(int i = 0; i < n; i++){
        for(int j = 0; j < n; j++){
            if(i != j && isAdj(wordList[i], wordList[j])){
                adj[wordList[i]].push_back(wordList[j]);
            }
        }
    }

    queue<string> q;
    unordered_map<string, bool> vis;
    q.push(beginWord);
    vis[beginWord] = true;
    int lvl = 1;

    // Perform BFS
    while(!q.empty()){
        int siz = q.size();
        while(siz--){
            string node = q.front();
            q.pop();
            if(node == endWord) return lvl;
            for(auto s : adj[node]){
                if(!vis[s]){
                    vis[s] = true;
                    q.push(s);
                }
            }
        }
        lvl++;
    }

    return 0;
}

