                return {-1};
        }
    }
    return dis;
}

statement:
The problem is to find the shortest distances between every pair of vertices in a given edge-weighted directed graph.
The graph is represented as an adjacency matrix of size n*n. Matrix[i][j] denotes the weight of the edge from i to j.
If Matrix[i][j] = -1, it means there is no edge from i to j.

Example:

Input: matrix = {{0, 25}, {-1, 0}}

Output: {{0, 25}, {-1, 0}}

solution:
void shortest_distance(vector<vector<int>>& matrix) {
    int v = matrix.size();

    for (int i = 0; i < v; i++) {
        for (int j = 0; j < v; j++) {
            if (matrix[i][j] == -1)
                matrix[i][j] = 1e9;
        }
    }

    for (int k = 0; k < v; k++) {
        for (int i = 0; i < v; i++) {
            for (int j = 0; j < v; j++) {
                if (i == j)
                    matrix[i][j] = 0;
                matrix[i][j] = min(matrix[i][j], (matrix[i][k] + matrix[k][j]));
            }
        }
    }

    for (int i = 0; i < v; i++) {
        for (int j = 0; j < v; j++) {
            if (matrix[i][j] == 1e9)
                matrix[i][j] = -1;
        }
    }
}

int findTheCity(int n, vector<vector<int>>& edges, int distanceThreshold) {
    vector<pair<int, int>> adj[n];
    for (auto e : edges) {
        adj[e[0]].push_back({e[1], e[2]});
        adj[e[1]].push_back({e[0], e[2]});
    }

    vector<int> dis(n, numeric_limits<int>::max());
    unordered_map<int, int> mp;

    for (int i = 0; i < n; i++) {
        dis[i] = 0;
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
        pq.push({0, i});

        while (!pq.empty()) {
            auto [uwt, u] = pq.top();
            pq.pop();

            for (auto [v, vwt] : adj[u]) {
                if (dis[v] > uwt + vwt) {
                    dis[v] = uwt + vwt;
                    pq.push({dis[v], v});
                }
            }
        }

        int nbrCnt = 0;
        for (int j = 0; j < n; j++) {
            if (i != j && dis[j] <= distanceThreshold)
                nbrCnt++;
            dis[j] = numeric_limits<int>::max();
        }
        mp[i] = nbrCnt;
    }

    int mini = numeric_limits<int>::max(), ans = 0;
    for (int i = 0; i < n; i++) {
        if (mp[i] < mini) {
            mini = mp[i];
            ans = i;
        } else if (mp[i] == mini)
            ans = max(ans, i);
    }

    return ans;
}

