            parent[uP] = vP;
            size[vP] += uSize;
        }
    }
};

bool isLand(int i, int j, vector<vector<int>>& grid){
    return (i >= 0 && i < grid.size() && j >= 0 && j < grid.size() && grid[i][j] == 1);
}

int largestIsland(vector<vector<int>>& grid) {
    int n = grid.size();

    vector<int> dr = {1, -1, 0, 0};
    vector<int> dc = {0, 0, 1, -1};

    DisjointSet djs(n * n);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] == 1) {
                int id = i * n + j;
                for (int d = 0; d < 4; d++) {
                    int ni = i + dr[d], nj = j + dc[d];
                    if (isLand(ni, nj, grid)) {
                        int nid = ni * n + nj;
                        if (djs.findUPar(id) != djs.findUPar(nid))
                            djs.unionBySize(id, nid);
                    }
                }
            }
        }
    }
    int ans = INT_MIN;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] == 0) {
                unordered_set<int> st;
                for (int d = 0; d < 4; d++) {
                    int ni = i + dr[d], nj = j + dc[d];
                    if (isLand(ni, nj, grid)) {
                        int nid = ni * n + nj;
                        st.insert(djs.findUPar(nid));
                    }
                }
                int siz = 0;
                for (auto u : st)
                    siz += djs.size[u];
                ans = max(ans, siz + 1);
            }
        }
    }
    for (int cellNo = 0; cellNo < n * n; cellNo++) {
        ans = max(ans, djs.size[djs.findUPar(cellNo)]);
    }
    return ans;
}

typedef pair<int, pair<int, int>> dup;

int swimInWater(vector<vector<int>>& grid) {
    int n = grid.size();

    vector<vector<bool>> vis(n, vector<bool>(n));
    priority_queue<dup, vector<dup>, greater<dup>> pq;
    pq.push({grid[0][0], {0, 0}});
    vis[0][0] = true;

    vector<int> dr = {-1, 1, 0, 0};
    vector<int> dc = {0, 0, -1, 1};

    int ans = 0;

    while (!pq.empty()) {
        auto [uwt, cord] = pq.top();
        pq.pop();
        int x = cord.first, y = cord.second;
        ans = max(ans, uwt);
        if (x == n - 1 && y == n - 1) return ans;
        for (int i = 0; i < 4; i++) {
            int nx = x + dr[i], ny = y + dc[i];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && !vis[nx][ny]) {
                vis[nx][ny] = true;
                pq.push({grid[nx][ny], {nx, ny}});
            }
        }
    }

    return ans;
}

int time;

void dfs(int node, int parent, int tin[], int low[], vector<int> adj[], vector<vector<int>>& ans, vector<bool>& vis) {
    vis[node] = true;
    low[node] = tin[node] = time;
    time++;

    for (auto v : adj[node]) {
        if (v == parent) continue;
        if (vis[v]) {
            low[node] = min(low[node], low[v]);
        } else {
            dfs(v, node, tin, low, adj, ans, vis);
            low[node] = min(low[node], low[v]);
            if (low[v] > tin[node])
                ans.push_back({v, node});
        }
    }
}

vector<vector<int>> criticalConnections(int n, vector<vector<int>>& connections) {
    time = 0;
    vector<int> adj[n];
    for (auto c : connections) {
        adj[c[0]].push_back(c[1]);
        adj[c[1]].push_back(c[0]);
    }
    vector<vector<int>> ans;
    vector<bool> vis(n);
    int tin[n], low[n];
    dfs(0, -1, tin, low, adj, ans, vis);
    return ans;
}

void topo(int node, vector<bool>& vis, vector<vector<int>>& adj, stack<int>& st) {
    vis[node] = true;
    for (auto v : adj[node]) {
        if (!vis[v]) {
            topo(v, vis, adj, st);
        }
    }
    st.push(node);
}

void dfs(int node, vector<bool>& vis, vector<int> revadj[]) {
    vis[node] = true;
    for (auto v : revadj[node]) {
        if (!vis[v]) {
            dfs(v, vis, revadj);
        }
    }
}

int kosaraju(int V, vector<vector<int>>& adj) {
    stack<int> st;
    vector<bool> vis(V);
    for (int i = 0; i < V; i++) {
        if (!vis[i])
            topo(i, vis, adj, st);
    }

    vector<int> revadj[V];
    for (int i = 0; i < V; i++) {
        for (auto j : adj[i]) {
            revadj[j].push_back(i);
        }
    }

    int ans = 0;
    vector<bool> visi(V);
    while (!st.empty()) {
        int node = st.top();
        st.pop();
        if (!visi[node]) {
            dfs(node, visi, revadj);
            ans++;
        }
    }
    return ans;
}

