        vector<int> curr(n);
        for(int j=0; j<n; j++){
            if(i==0){
                curr[j] = mat[i][j];
                continue;
            }
            int a = 1e9, c = 1e9;
            if(j-1>=0) a = prev[j-1];
            int b = prev[j];
            if(j+1<n) c = prev[j+1];
            curr[j] = min(a,min(b,c))+mat[i][j];
        }
        prev = curr;
    }
    int ans = INT_MAX;
    for(auto i:prev) ans = min(ans,i);
    return ans;
}

