    for (int i = 0; i < n; i++) {
        for (int prev = 0; prev < i; prev++) {
            if (nums[prev] < nums[i]) {
                if (dp[i] == dp[prev] + 1) {
                    cnt[i] += cnt[prev];
                } else if (dp[prev] + 1 > dp[i]) {
                    dp[i] = dp[prev] + 1;
                    cnt[i] = cnt[prev];
                }
            }
        }
    }

    int lis = *max_element(dp.begin(), dp.end());
    int ans = 0;

    for (int i = 0; i < n; i++) {
        if (dp[i] == lis) {
            ans += cnt[i];
        }
    }

    return ans;
}

