    for(int k=i; k<j; k++){
        int cost = arr[i-1]*arr[k]*arr[j] + fmemo(i,k,arr,dp) + fmemo(k+1,j,arr,dp);
        mini = min(cost,mini);
    }
    return dp[i][j] = mini;
}

