int kthLargest(const vector<int>& nums, int k) {
    if (k < 1 || k > (int)nums.size()) throw invalid_argument("invalid k");
    priority_queue<int, vector<int>, greater<int>> heap;
    for (int x : nums) {
        heap.push(x);
        if ((int)heap.size() > k) heap.pop();
    }
    return heap.top();
}

