vector<int> mergeArrays(const vector<vector<int>>& arrays) {
    using Item = tuple<int,int,int>;
    priority_queue<Item, vector<Item>, greater<Item>> heap;
    for (int i = 0; i < (int)arrays.size(); ++i)
        if (!arrays[i].empty()) heap.emplace(arrays[i][0], i, 0);
    vector<int> result;
    while (!heap.empty()) {
        auto [value, i, j] = heap.top(); heap.pop();
        result.push_back(value);
        if (j + 1 < (int)arrays[i].size()) heap.emplace(arrays[i][j+1], i, j+1);
    }
    return result;
}

