class MinHeap {
    vector<int> a;
public:
    void push(int x) {
        a.push_back(x);
        int i = (int)a.size() - 1;
        while (i > 0 && a[i] < a[(i-1)/2]) {
            swap(a[i], a[(i-1)/2]); i = (i-1)/2;
        }
    }
    int top() const {
        if (a.empty()) throw out_of_range("empty heap");
        return a[0];
    }
    void pop() {
        if (a.empty()) throw out_of_range("empty heap");
        a[0] = a.back(); a.pop_back();
        int i = 0;
        while (2*i+1 < (int)a.size()) {
            int child = 2*i+1;
            if (child+1 < (int)a.size() && a[child+1] < a[child]) ++child;
            if (a[i] <= a[child]) break;
            swap(a[i], a[child]); i = child;
        }
    }
};

