int minPlatforms(vector<int> arrivals, vector<int> departures) {
    if (arrivals.size() != departures.size()) throw invalid_argument("size mismatch");
    sort(arrivals.begin(), arrivals.end());
    sort(departures.begin(), departures.end());
    int i=0, j=0, active=0, answer=0, n=(int)arrivals.size();
    while (i<n) {
        if (j==n || arrivals[i]<=departures[j]) {
            ++active; ++i; answer=max(answer,active);
        } else { --active; ++j; }
    }
    return answer;
}

