bool canJump(const vector<int>& nums) {
    if (nums.empty()) return false;
    long long farthest=0;
    for (int i=0; i<(int)nums.size(); ++i) {
        if (i>farthest) return false;
        farthest=max(farthest,(long long)i+nums[i]);
        if (farthest >= (int)nums.size()-1) return true;
    }
    return false;
}

#include <vector>
#include <algorithm>
#include <stdexcept>
using namespace std;

struct Item { double value, weight; };
double fractionalKnapsack(vector<Item> items, double capacity) {
    if (capacity<0) throw invalid_argument("negative capacity");
    for (auto item:items)
        if (item.weight<=0 || item.value<0) throw invalid_argument("invalid item");
    sort(items.begin(), items.end(), [](const Item& a,const Item& b) {
        return a.value/a.weight > b.value/b.weight;
    });
    double value=0;
    for (auto item:items) {
        double used=min(capacity,item.weight);
        value += used*item.value/item.weight; capacity-=used;
        if (capacity<=0) break;
    }
    return value;
}
